scene.add(ax);

// Asymptotes at x = pi/2 + k*pi
const asyms = [];
for (let k = -2; k <= 1; k++) {
  const x = Math.PI/2 + k*Math.PI;
  const p1 = ax.c2p(x, -4);
  const p2 = ax.c2p(x, 4);
  const l = new Line({ start: p1, end: p2, color: RED });
  l.setStrokeWidth(2);
  l.setOpacity(0.7);
  asyms.push(l);
